code_examples.code:
def greet(name):
    print("Hello", name)

greet("Abhi")

def show_details(**details):
    for key, value in details.items():
        print(key, value)

show_details(name="Abhi", age=25, city="Bengaluru")

def introduce(name, age):
    print(name, age)

values = ["Abhi", 25]
data = {"name": "Abhi", "age": 25}

introduce(*values)
introduce(**data)

def create_user(name, *, age, city):
    print(name, age, city)

create_user("Abhi", age=25, city="Bengaluru")

def add(a, b, /):
    return a + b

print(add(10, 20))

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

print(factorial(5))

def square(x):
    return x * x

def apply_function(func, value):
    return func(value)

print(apply_function(square, 5))

def outer():
    def inner():
        print("Inside inner function")

    inner()

outer()
